"""Graceful A2A ``EventQueue`` / ``TaskUpdater`` publish helpers (client disconnect)."""

from __future__ import annotations

from collections.abc import Awaitable, Callable
from enum import Enum

import structlog
from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import Part, TextPart

structlogger = structlog.get_logger()


class A2ATaskPublishOperation(str, Enum):
    """``TaskUpdater`` operations logged when publishing A2A task events."""

    START_WORK = "start_work"
    ADD_ARTIFACT = "add_artifact"
    SUBMIT = "submit"
    COMPLETE = "complete"
    FAILED = "failed"
    REJECT = "reject"
    CANCEL = "cancel"
    REQUIRES_INPUT = "requires_input"
    REQUIRES_AUTH = "requires_auth"
    UNKNOWN = "unknown"


def _is_terminal_state_conflict(exc: RuntimeError) -> bool:
    message = str(exc).lower()
    return "terminal state" in message or "already terminal" in message


class A2ATaskEventPublisher:
    """Publishes task events without raising when the consumer has gone away.

    The a2a-sdk ``EventQueue`` drops enqueues silently when closed; ``TaskUpdater``
    raises ``RuntimeError`` when a second terminal update is attempted. Dialogue
    processing must continue and in-memory task-cycle state must still close
    even when events are not delivered.
    """

    def __init__(self, updater: TaskUpdater) -> None:
        self._updater = updater
        self._queue_closed_logged = False

    @property
    def updater(self) -> TaskUpdater:
        return self._updater

    @property
    def queue_closed(self) -> bool:
        queue = getattr(self._updater, "event_queue", None)
        if queue is None:
            return False
        is_closed = getattr(queue, "is_closed", None)
        if callable(is_closed):
            return is_closed()
        return False

    def _log_queue_closed(self, *, operation: A2ATaskPublishOperation) -> None:
        if self._queue_closed_logged:
            return
        self._queue_closed_logged = True
        structlogger.warning(
            "a2a_server.a2a_task_event_publisher.queue_closed",
            operation=operation,
            task_id=self._updater.task_id,
            context_id=self._updater.context_id,
        )

    async def publish_non_terminal(
        self,
        operation: A2ATaskPublishOperation,
        publish: Callable[[], Awaitable[None]],
    ) -> None:
        """Publish a non-terminal update; skip quietly when the queue is closed."""
        if self.queue_closed:
            self._log_queue_closed(operation=operation)
            return
        try:
            await publish()
        except RuntimeError as exc:
            if _is_terminal_state_conflict(exc):
                structlogger.debug(
                    "a2a_server.a2a_task_event_publisher.skipped_terminal",
                    operation=operation,
                    task_id=self._updater.task_id,
                    context_id=self._updater.context_id,
                )
                return
            raise
        if self.queue_closed:
            self._log_queue_closed(operation=operation)

    async def publish_terminal(
        self,
        operation: A2ATaskPublishOperation,
        publish: Callable[[], Awaitable[None]],
    ) -> None:
        """Publish a terminal update; never raise on queue closed or
        duplicate terminal."""
        try:
            await publish()
        except RuntimeError as exc:
            if not _is_terminal_state_conflict(exc):
                raise
            structlogger.debug(
                "a2a_server.a2a_task_event_publisher.skipped_terminal",
                operation=operation,
                task_id=self._updater.task_id,
                context_id=self._updater.context_id,
            )
        if self.queue_closed:
            self._log_queue_closed(operation=operation)


async def publish_task_failure(updater: TaskUpdater, *, message: str) -> None:
    """Publish ``failed`` for executor-level errors without raising on disconnect."""
    publisher = A2ATaskEventPublisher(updater)

    async def _failed() -> None:
        await updater.failed(
            updater.new_agent_message([Part(root=TextPart(text=message))])
        )

    await publisher.publish_terminal(A2ATaskPublishOperation.FAILED, _failed)
